/** Refund one whole line: its net, less its share of the order discount, plus the tax charged on it. */
export function refundLine(ctx: AppContext, id: string, productId: string): InvoiceRefund {
  const invoice = getInvoice(ctx, id);
  if (invoice.status !== 'paid') throw conflict(`invoice ${invoice.number} is ${invoice.status}`);
  const line = invoice.lines.find((l) => l.productId === productId);
  if (!line) throw notFound('invoice line');
  const refunds = invoice.refunds ?? [];
  if (refunds.some((r) => r.productId === productId)) throw conflict(`line ${productId} is already refunded`);
  const refund = {
    productId,
    amount: line.net - line.discount + line.tax,
    createdAt: ctx.clock.now().toISOString(),
  };
  ctx.store.invoices.update(id, { refunds: [...refunds, refund] });
  return refund;
}
